def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max({v for row in grid for v in row}, key=lambda v: sum(row.count(v) for row in grid))
    # For each color, find its boundary component and interior signal points.
    # The border seed color is propagated along the signal's row/column as shown
    # by the demonstrations; the signal itself is replaced with 4.
    bars = []
    for r in (0, h-1):
        c = 0
        while c < w:
            v = grid[r][c]
            e = c + 1
            while e < w and grid[r][e] == v:
                e += 1
            if v != bg and e-c >= 3:
                bars.append((r, c, e-1, v))
            c = e
    blocked = {(r,c) for r,a,b,v in bars for c in range(a,b+1)}
    points = [(r,c,grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and (r,c) not in blocked]
    for r,c,v in points:
        out[r][c] = 4
        # Draw the color through the point's column; preserve all original non-background cells.
        for y in range(h):
            if grid[y][c] == bg:
                out[y][c] = v
        # For two boundary bars, project the point to the corresponding boundary span.
        for br,a,b,bv in bars:
            if a <= c <= b:
                for y in range(min(r,br), max(r,br)+1):
                    for x in range(a,b+1):
                        if grid[y][x] == bg:
                            out[y][x] = v
    return out
